@startuml

class Employee {}

class HeadCoach extends Employee {}

class Director extends Employee {}

class Scout extends Employee {}

class HeadScout extends Scout {}

class PlayerProfile {
  + targetPositions : string[]
}

class PlayerAttribute {
  + name : string
  + value : float
}

class Player {
  + name : string
}

class LongListEntry {
  + date : date
}

class ScoutingAssignment {
  + status : string
}

class ScoutingReport {
  + pros : string
  + cons : string
  + recommendation : string
}

class ShortList {}

class OfficialOffer {}

PlayerProfile "1" *-- "* PlayerAttribute" PlayerAttribute
PlayerProfile "1" -- "*" LongListEntry
LongListEntry "*" -- "1" Player
Scout "1" -- "*" ScoutingAssignment
Scout "1" -- "*" ScoutingReport
ScoutingAssignment "1" -- "1" ScoutingReport
ScoutingAssignment "1" -- "1" Player
ScoutingAssignment "1" -- "0..1 Scout" Scout
ShortList "*" -- "1" Player
Director "1" -- "*" OfficialOffer
OfficialOffer "*" -- "1" Player

@enduml

